await test('simple sourcing saves specific targets, location policy, one purchase cap, and daily AI guard',async()=>{q.openHunt();assert(d.querySelector('[name=targets]'));assert(d.querySelector('[name=city]'));assert(d.querySelector('[name=originAddress]'));assert(d.querySelector('[name=autoRejectOutside]'));assert(d.querySelector('[name=radius]'));assert(d.querySelector('[name=price]'));assert(d.querySelector('[name=budget]'));assert(!d.querySelector('[name=maxOffer]'));assert.equal(d.querySelector('[name=space]').selectedOptions[0].textContent,'Fits in a car');assert.equal(d.querySelector('[name=aiDailyLimit]').closest('details').open,false);d.querySelector('[name=targets]').value='vintage furniture\niPhone 8, Vintage Furniture';d.querySelector('[name=autoRejectOutside]').checked=true;await submit('#source-form',{budget:2000,city:'Toronto, ON',originAddress:'100 Example Street, Toronto, ON',radius:35,price:450,mode:'Find only',profit:40,roi:25,space:'Car boot',aiDailyLimit:80});assert.deepEqual(Array.from(q.auto.sourcing.targets),['vintage furniture','iPhone 8']);assert.equal(q.auto.sourcing.preset,'custom');assert.equal(q.auto.sourcing.aiDailyLimit,80);assert.equal(q.auto.sourcing.city,'Toronto, ON');assert.equal(q.auto.sourcing.originAddress,'100 Example Street, Toronto, ON');assert.equal(q.auto.sourcing.outsideRange,'reject');assert.equal(q.auto.maxOffer,450);assert.equal(JSON.parse(w.vectorSnapshot()).radius,35);assert.equal(JSON.parse(w.vectorSnapshot()).maxPrice,450);assert.equal(q.auto.keywords,'');assert.equal(q.auto.mode,'Find only')});
await test('switching to find and negotiate queues an immediate scan',async()=>{const before=JSON.parse(w.vectorSnapshot());q.state.scanning=true;q.state.jobs=[];q.lanes.Buying=true;q.auto.mode='Find only';q.openHunt();await submit('#source-form',{mode:'Auto-negotiate'});assert.equal(q.auto.mode,'Auto-negotiate');assert(q.state.jobs.some(j=>j.kind==='scan'&&j.state==='queued'));assert(d.querySelector('#mp-core-buying').textContent.includes('Find and negotiate'));q.hydrate(before);q.navigate('Stock')});
await test('sourcing query plan keeps exact intent and learns bounded exact-model searches',()=>{const before=JSON.parse(w.vectorSnapshot());q.auto.sourcing={preset:'custom',targets:['iphone'],minROI:30,space:'Car boot',aiDailyLimit:100,maxDiscount:20};q.state.sourceLearnedQueries=[];assert.deepEqual(Array.from(q.normalizeSourcingTargets('Aeron chair, aeron chair\niPhone 8')),['Aeron chair','iPhone 8']);assert.deepEqual(Array.from(q.sourceTargetVariants('vintage chairs')),['vintage chairs','vintage chair']);assert.deepEqual(Array.from(q.sourceTargetVariants('iPhone 8')),['iPhone 8']);q.learnSourceQuery('iphone','Apple iPhone 12 64GB');q.learnSourceQuery('iphone','Apple iPhone 13 128GB');assert.deepEqual(Array.from(q.sourceQueryPlan()),['iphone','iphones','Apple iPhone 12 64GB','Apple iPhone 13 128GB']);q.learnSourceQuery('iphone','Samsung Galaxy S23');assert.equal(q.sourceQueryPlan().includes('Samsung Galaxy S23'),false);for(let model=14;model<=20;model++)q.learnSourceQuery('iphone','Apple iPhone '+model);assert.equal(q.state.sourceLearnedQueries.filter(x=>x.root.toLowerCase()==='iphone').length,6);q.learnSourceQuery('unrelated','Dyson V8');assert.equal(q.sourceQueryPlan().includes('Dyson V8'),false);q.hydrate(before)});
