await test('sourcing ranks local identified cards ahead of risky or remote cards without AI',()=>{const local={text:'DEWALT DCD777 40 Used Good Toronto ON'},remote={text:'DEWALT DCD777 40 Used Good Brampton ON'},broken={text:'DEWALT DCD777 40 Used Good Toronto ON not working'};assert(q.sourceCardPriority(local)>q.sourceCardPriority(remote));assert(q.sourceCardPriority(local)>q.sourceCardPriority(broken))});
await test('sourcing values multiple observed comparables and handles malformed evidence',()=>{const url=n=>'https://www.facebook.com/marketplace/item/'+n+'/',item={name:'Acme Maker',url:url(701),ask:110,resale:200,costs:15,category:'Electronics',condition:'Good',distanceKm:5,assessment:{model:'Acme Maker',quote:'Acme Maker 110 working',size:'One shelf',risks:[],comparables:[180,190,200].map((ask,i)=>({url:url(702+i),ask,quote:'Acme Maker '+ask+' working'}))}},evidence=[{url:item.url,text:item.assessment.quote,listings:[]},...item.assessment.comparables.map(c=>({url:c.url,text:c.quote,listings:[]}))];q.auto.priceEnabled=true;let a=q.assessSource(item,evidence);assert(a.eligible,'three verified comparables should qualify');assert.equal(a.resale,171);assert.equal(a.ceiling,116);assert.equal(a.demand,'Stronger price evidence');const two=q.assessSource(item,evidence.slice(0,3));assert(two.eligible,'two verified comparables should qualify');assert.equal(two.resale,162);assert.equal(two.demand,'Moderate price evidence');assert(!q.assessSource(item,evidence.slice(0,2)).eligible);item.assessment.valuation={low:170,expected:185,high:200,confidence:'Medium',rationale:'Good-condition comparisons support this range; lower end allows a faster sale.'};const agent=q.assessSource(item,evidence);assert.equal(agent.resale,170);assert.equal(agent.valuation.expected,185);assert(agent.basis.includes('AI resale range'));item.assessment.valuation.confidence='Low';a=q.assessSource(item,evidence);assert(a.eligible,JSON.stringify(a.why));assert.equal(a.resale,171,'verified comparables provide a conservative fallback when the AI range is weak');item.assessment.valuation.confidence='Medium';item.assessment.valuation.low=250;a=q.assessSource(item,evidence);assert(a.eligible,JSON.stringify(a.why));assert.equal(a.resale,171,'an invalid AI range cannot veto or inflate verified comparable fallback');delete item.assessment.valuation;item.assessment.comparables={bad:true};assert(!q.assessSource(item,evidence).eligible)});
await test('one exact comparable qualifies only a fully verified deep discount',()=>{const before=JSON.parse(w.vectorSnapshot()),url=n=>'https://www.facebook.com/marketplace/item/'+n+'/',item={name:'Acme Maker 500',url:url(706),ask:30,resale:0,costs:15,category:'Electronics',condition:'Used - Good',distanceKm:5,location:'Toronto, ON',assessment:{model:'Acme Maker 500',quote:'Acme Maker 500 30 Used Good Toronto ON',size:'One shelf',risks:[],comparables:[{url:url(707),ask:180,quote:'Acme Maker 500 180 Used Good'}]}},evidence=[{url:item.url,text:item.assessment.quote,listings:[]},{url:item.assessment.comparables[0].url,text:item.assessment.comparables[0].quote,listings:[]}];q.auto.priceEnabled=true;let a=q.assessSource(item,evidence);assert(a.eligible);assert.equal(a.resale,135);assert.equal(a.basis,'One comparable asking price, discounted 25%');assert.equal(a.demand,'Limited price evidence');item.ask=100;item.assessment.quote='Acme Maker 500 100 Used Good Toronto ON';evidence[0].text=item.assessment.quote;a=q.assessSource(item,evidence);assert(!a.eligible);assert(a.why.includes('Need stronger price evidence'));item.ask=30;item.assessment.quote='Acme Maker 500 30 Toronto ON';evidence[0].text=item.assessment.quote;a=q.assessSource(item,evidence);assert(!a.eligible);assert(a.why.includes('Need stronger price evidence'));item.assessment.quote='Acme Maker 500 30 Used Good Toronto ON';evidence[0].text=item.assessment.quote;item.distanceKm=-1;item.location='Richmond Hill, ON';a=q.assessSource(item,evidence);assert(!a.eligible);assert(a.why.includes('Need stronger price evidence'));q.hydrate(before)});
await test('verified search city can qualify with pickup distance pending',()=>{const before=JSON.parse(w.vectorSnapshot()),url=n=>'https://www.facebook.com/marketplace/item/'+n+'/',item={name:'Acme Maker',url:url(711),ask:90,resale:200,costs:15,category:'Electronics',condition:'Good',distanceKm:-1,location:'Toronto, ON',assessment:{model:'Acme Maker',quote:'Acme Maker 90 working Toronto, ON',size:'One shelf',risks:[],comparables:[180,190,200].map((ask,i)=>({url:url(712+i),ask,quote:'Acme Maker '+ask+' working'}))}},evidence=[{url:item.url,text:item.assessment.quote,listings:[]},...item.assessment.comparables.map(c=>({url:c.url,text:c.quote,listings:[]}))];q.auto.sourcing={...q.auto.sourcing,city:'Toronto, ON'};q.auto.priceEnabled=true;let a=q.assessSource(item,evidence);assert.equal(a.distanceKm,-1);assert.equal(a.distanceStatus,'pending');assert(a.eligible);item.location='Richmond Hill, ON';item.assessment.quote='Acme Maker 90 working Richmond Hill, ON';evidence[0].text=item.assessment.quote;a=q.assessSource(item,evidence);assert.equal(a.distanceKm,-1);assert(!a.eligible);assert(a.why.includes('Outside search city or location unverified'));q.hydrate(before)});
await test('seller pickup location becomes a visible calculated buying distance',async()=>{const before=JSON.parse(w.vectorSnapshot()),r={id:718,name:'Acme Maker',view:'Buying',category:'Electronics',location:'Toronto, ON',ask:90,offer:85,resale:170,costs:15,url:'https://www.facebook.com/marketplace/item/718/',assessment:{eligible:true,resale:170,costs:15}};q.rows.push(r);q.auto.sourcing={...q.auto.sourcing,city:'Toronto, ON',originAddress:'100 Example Street, Toronto, ON',outsideRange:'review'};const result=await q.resolveBuyingDistance(r,{pickup:{location:'Yonge Street and Finch Avenue'}});assert.equal(result.distanceKm,12.4);assert.equal(result.outside,false);assert.equal(r.pickupDistanceStatus,'within');q.navigate('Buying');assert(d.querySelector('[data-id="718"]').textContent.includes('12.4 km'));assert(d.querySelector('[data-id="718"]').textContent.includes('pickup distance'));q.hydrate(before);q.navigate('Stock')});
await test('sourcing matches separated keywords, split brands, and canonical model evidence',()=>{const before=JSON.parse(w.vectorSnapshot()),url=n=>'https://www.facebook.com/marketplace/item/'+n+'/',item={name:'DEWALT 20V Cordless Brushless Compact Drill Driver DCD777',url:url(721),ask:40,resale:100,costs:15,category:'Home Improvement Supplies',condition:'Used - Good',distanceKm:0,location:'Toronto, ON',assessment:{model:'DEWALT DCD777',quote:'summary only',size:'One shelf',risks:[],comparables:[90,100,110].map((ask,i)=>({url:url(722+i),ask,quote:'DEWALT DCD777 '+ask+' Used Good'}))}},evidence=[{url:item.url+'?ref=search',text:'DEWALT 20V Cordless Brushless Compact Drill Driver model DCD777 40 Used Good Toronto ON',listings:[]},...item.assessment.comparables.map(c=>({url:c.url+'?tracking=test',text:c.quote,listings:[]}))];q.auto.keywords='cordless drill';const a=q.assessSource(item,evidence);assert(q.matchesSourceKeywords(item.name,q.auto.keywords));assert(q.sourceHasTerms('DEWALT DCD777',evidence[0].text));assert(q.sourceModelMatch('iPhone 12','I phone 12 128GB'));assert.equal(a.comparables.length,3);assert(!a.why.includes('Brand/model unclear'));assert(!a.why.includes('Details not verified'));assert(!a.why.includes('Title outside search'));q.hydrate(before)});
