await test('legacy and mismatched sourcing cards leave Discover and old fingerprints are rechecked',()=>{const before=JSON.parse(w.vectorSnapshot()),legacy={...before,rows:[{id:991,name:'Legacy chair',view:'Discover',ask:0,offer:0,resale:80,costs:0,url:'https://www.facebook.com/marketplace/item/991/'},{id:992,name:'Old comparable rule',view:'Discover',ask:25,offer:20,resale:90,costs:15,url:'https://www.facebook.com/marketplace/item/992/',assessment:{status:'Review',eligible:false,basis:'AI estimate only',why:['Need 3 comparable listings']}},{id:993,name:'Jinyu BDZ-155B',view:'Discover',ask:20,offer:20,resale:20,costs:15,url:'https://www.facebook.com/marketplace/item/993/',assessment:{status:'Review',eligible:false,basis:'AI estimate only',model:'Jinyu BDZ-155B',why:['Need 2 comparable listings'],comparables:[{url:'https://www.facebook.com/marketplace/item/994/',ask:20,quote:'Slikey BDZ-155B 20 New'}]}}],nativeState:{...before.nativeState,jobs:[],pickups:[],sourcingPolicyVersion:0,sourceFeeds:{chair:{version:3,cards:{'https://www.facebook.com/marketplace/item/991/':'same'}}}},auto:{...before.auto,sourcing:{preset:'compact',minROI:30,space:'One shelf'}}};q.hydrate(legacy);for(const row of q.rows){assert.equal(row.view,'Excluded');assert.equal(row.assessment.status,'Review');assert.equal(row.assessment.eligible,false);assert.equal(row.assessment.basis,'Research required');assert.equal(row.resale,0)}assert.equal(q.rows[0].assessment.why.join('|'),'Outdated sourcing result');assert.equal(q.rows[1].assessment.why.join('|'),'Outdated sourcing result');assert.equal(q.rows[2].assessment.why.join('|'),'Outdated comparable evidence');assert.equal(q.state.sourcingPolicyVersion,5);assert.equal(Object.keys(q.state.sourceFeeds).length,0);assert.equal(q.auto.sourcing.space,'Car boot');assert.equal(q.sourceFeedDelta('chair',{listings:[{url:q.rows[0].url,text:'same'}]}).known,false);q.hydrate(before);q.navigate('Stock')});
