await test('accepted deals consume the commitment limit before and after pickup is scheduled',()=>{const saved=w.vectorSnapshot();q.state.pickups=[];q.auto.budget=2000;const accepted={id:901,name:'Accepted chair',view:'Buying',offer:50};q.rows.push(accepted);q.workFor(accepted).committedPrice=50;q.openHunt();let note=d.querySelector('.vx-capital-note');assert(note.textContent.includes('$1,950 available for accepted deals'));assert(note.textContent.includes('$50 committed to 1 accepted deal'));assert(note.textContent.includes('Negotiations do not reserve funds'));assert.equal(note.dataset.warning,undefined);q.state.pickups=[{itemId:accepted.id,leadURL:'https://www.facebook.com/messages/t/901',name:'Chair',person:'Seller',side:'Buying',price:130,location:'Test',timeText:'Tomorrow',startsAt:new Date(Date.now()+86400000).toISOString(),quotes:[],state:'Ready',key:'test'}];q.openHunt();note=d.querySelector('.vx-capital-note');assert(note.textContent.includes('$1,870 available for accepted deals'),'scheduled pickup replaces rather than duplicates the earlier commitment');assert(note.textContent.includes('$130 committed to 1 accepted deal'));assert.throws(()=>q.applySourcingPreset('compact',100),/accepted deals/);q.hydrate(JSON.parse(saved));q.navigate('Discover')});
await test('pickup requires mutual agreement, future time, location and allowed price',()=>{const r={id:901,name:'Test tool',view:'Buying',offer:100},url='https://www.facebook.com/messages/t/901',startsAt=new Date(Date.now()+86400000).toISOString(),pickup={agreed:true,cancelled:false,price:90,startsAt,timeText:'tomorrow at noon',location:'123 Test Street',ourQuote:'I can collect tomorrow at noon for 90.',theirQuote:'Agreed. Meet at 123 Test Street.',priceQuote:'I can collect tomorrow at noon for 90.',timeQuote:'I can collect tomorrow at noon for 90.',locationQuote:'Agreed. Meet at 123 Test Street.'},lead={id:'Seller',url,state:'Pickup booked',pickup},ev=[{url,text:pickup.ourQuote+' '+pickup.theirQuote,listings:[]}];assert(q.pickupFromLead(r,lead,ev));assert.equal(q.pickupFromLead(r,lead,[]),null);assert.equal(q.pickupFromLead(r,{...lead,pickup:{...pickup,price:900}},ev),null);assert.equal(q.pickupFromLead(r,{...lead,pickup:{...pickup,startsAt:'2020-01-01T00:00:00Z'}},ev),null);q.updatePickup(r,lead,ev);q.updatePickup(r,lead,ev);assert.equal(q.activePickups().length,1);q.openPickups();assert(d.querySelector('#mp-settings').textContent.includes('123 Test Street'));q.updatePickup({...r,id:902},lead,ev);assert.equal(q.activePickups()[1].state,'Time conflict');q.updatePickup(r,{...lead,pickup:{...pickup,cancelled:true}},ev);assert.equal(q.state.pickups[0].state,'Cancelled');q.state.pickups=[];q.navigate('Stock')});
