await test('agent pricing accepts varied products without exact text or fixed comparable counts',()=>{for(const name of ['iPhone 11 64GB','Cordless drill with batteries','Oak dining chair','Vintage sewing machine']){const url='https://www.facebook.com/marketplace/item/800/',result={ask:137,minimum:112,rationale:'Condition-adjusted local asking evidence',sources:[{url,price:150,reason:'Comparable with different accessories'}],needsHuman:false};const ev=[{url,text:'Different product wording and formatting',listings:[]}],r={name,offer:0,costKnown:false},fallback=q.resalePlan(r,result,ev),reported=q.resalePlan(r,{...result,marketLow:120,marketHigh:170},ev);assert.equal(fallback.ask,137);assert.deepEqual([fallback.marketLow,fallback.marketHigh],[150,150]);assert.deepEqual([reported.marketLow,reported.marketHigh],[120,170]);assert.throws(()=>q.resalePlan(r,result,[]),/observed source/);assert.throws(()=>q.resalePlan({...r,offer:200,costKnown:true},result,ev),/profit target/);assert.throws(()=>q.resalePlan(r,{...result,minimum:200},ev),/incomplete/);assert.throws(()=>q.resalePlan(r,{...result,needsHuman:true,question:'Which model?'},ev),/Which model/);}});
