await test('manual refresh supersedes a paused automatic read without resuming replies',()=>{const before=JSON.parse(w.vectorSnapshot()),r={id:916,name:'Held phone',view:'Buying',url:'https://www.facebook.com/marketplace/item/916/',ask:150,offer:130,resale:220,costs:10,pickupDistanceStatus:'outside',pickupDistanceKm:9},url='https://www.facebook.com/messages/t/916';q.rows.push(r);q.lanes.Buying=true;const work=q.workFor(r);work.enabled=false;work.leads=[{id:'Seller',url:'',last:'',reply:'Original offer',sent:1},{id:'Real seller',url,last:'6:30pm',unanswered:true,state:'Negotiating',sent:1}];const automatic={id:'held-auto',kind:'sync',itemId:r.id,state:'queued',recurring:true,incremental:true,targetCandidateKeys:['old-key']},reply={id:'held-reply',kind:'reply',itemId:r.id,state:'needs_you',leadURL:url,note:'Pickup is 9 km. Review this deal before replying.'},other={id:'other-sync',kind:'sync',itemId:999,state:'queued',recurring:true};q.state.jobs=[automatic,reply,other];assert.equal(q.jobAllowed(automatic),false);q.navigate('Buying');click('[data-id="916"] summary');assert.equal(work.leads.length,2);assert(!d.querySelector('#mp-lead-select'));assert(d.querySelector('#mp-detail').textContent.includes('Real seller'));assert(!d.querySelector('#mp-detail').textContent.includes('Original offer'));assert.equal(d.querySelector('#native-refresh-conversation').disabled,false);click('#native-refresh-conversation');const manual=q.state.jobs.find(j=>j.kind==='sync'&&j.itemId===r.id&&j.state==='queued');assert.equal(automatic.state,'cancelled');assert(manual);assert.equal(manual.recurring,undefined);assert.equal(q.jobAllowed(manual),true);assert.deepEqual(Array.from(manual.targetCandidateKeys),[url]);assert.equal(work.enabled,false);assert.equal(r.distanceApproved,undefined);assert.equal(reply.state,'needs_you');assert.equal(other.state,'queued');assert.equal(d.querySelector('#native-refresh-conversation').disabled,true);q.render();assert.equal(q.state.jobs.filter(j=>j.kind==='sync'&&j.itemId===r.id&&j.state==='queued').length,1);q.hydrate(before);q.navigate('Stock')});
