await test('outdated companion is not green, holds jobs, and recovers without opening Connections',async()=>{const before=JSON.parse(w.vectorSnapshot());chromeReadiness='legacy';q.openConnections();await wait(20);assert.equal(d.querySelector('[data-health="Chrome"]').textContent,'Update needed');assert.equal(d.querySelector('[data-health="Chrome"]').dataset.connected,'false');assert(d.querySelector('#native-connection-status').textContent.includes('Reload'));q.state.jobs=[];q.state.connected=true;q.state.scanning=false;q.lanes.Selling=true;const job=q.queueJob('price',q.rows[1]);await q.tickWorker();assert.equal(job.state,'needs_you');assert(job.note.includes('running companion needs an update'));chromeReadiness='document-v6';q.state.connected=false;q.state.nextCompanionProbe=0;await q.tickWorker();assert.equal(job.state,'queued');assert(job.note.includes('Companion reconnected'));assert.equal(d.querySelector('[data-health="Chrome"]').textContent,'Connected','background recovery refreshes the visible health label');assert.equal(d.querySelector('[data-health="Chrome"]').dataset.connected,'true');assert.equal(d.querySelector('#native-connection-status').textContent,'','obsolete companion instructions are cleared');q.hydrate(before);q.navigate('Stock')});
