await test('blocker banner opens only the affected issue group before the full action center',()=>{const before=JSON.parse(w.vectorSnapshot());q.state.jobs=[{id:'pin-a',kind:'sync',itemId:q.rows[0].id,state:'needs_you',note:'Restore your Messenger history in Chrome. PIN required.'},{id:'pin-b',kind:'sync',itemId:q.rows[1].id,state:'needs_you',note:'Restore your Messenger history in Chrome. PIN required.'},{id:'other-task',kind:'scan',state:'needs_you',note:'Could not verify location.'}];q.state.dismissedBlockers=[];q.state.notifiedBlockers=[];const notices=()=>calls.filter(m=>m.method==='attention'&&m.args.notify!==false).length,initial=notices();q.render();const banner=d.querySelector('#va-blocker');assert(banner.textContent.includes('Restore your Messenger chats'));assert(banner.textContent.includes('2 tasks in this alert'));assert(banner.textContent.includes('other issue'));assert.equal(notices(),initial+1);q.render();assert.equal(notices(),initial+1);click('#va-blocker-review');assert(!d.querySelector('#va-blocker'),'global warning is hidden inside Needs attention');assert.equal(d.querySelectorAll('#va-blocked-tasks .va-issue').length,1,'focused resolution does not show unrelated groups');assert(d.querySelector('#va-blocked-tasks').textContent.includes('Open Chrome'));assert(!d.querySelector('#va-blocked-tasks').textContent.includes('Could not verify location.'));assert(d.querySelector('#va-show-all').textContent.includes('Show all'));click('#va-show-all');assert(d.querySelector('#va-blocked-tasks').textContent.includes('Could not verify location.'));click('#va-nav');assert(!d.querySelector('#va-blocker'));q.state.jobs.forEach(j=>j.state='done');q.render();assert(!d.querySelector('#va-blocker'));assert(!d.querySelector('#va-blocked-tasks'));q.navigate('Stock');q.state.jobs[0].state='needs_you';q.render();assert(d.querySelector('#va-blocker'));assert.equal(notices(),initial+2);q.hydrate(before);q.navigate('Stock')});

